async function run() {
  const loc = params.location;
  const from = dates.today();
  const to = dates.addDays(from, 1);

  const events = await calendar.events({ from, to });
  const emails = await gmail.search({ query: "in:inbox is:unread", unread: true, days: 1, max: 20 });

  const importantEmails = [];
  for (const email of emails) {
    const verdict = await judge.important(email);
    if (verdict.p >= 0.5) importantEmails.push(email);
  }

  const url = "https://api.open-meteo.com/v1/forecast?latitude=" + loc.latitude +
    "&longitude=" + loc.longitude +
    "&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max" +
    "&timezone=" + encodeURIComponent(loc.timezone) +
    "&forecast_days=1";
  const weather = await http.getJSON(url);

  const sortedEvents = events.slice().sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

  const lines = [];
  lines.push("Bom dia! Resumo de " + dates.format(now(), "EEEE, dd/MM"));
  lines.push("");
  lines.push("Agenda:");
  if (sortedEvents.length === 0) {
    lines.push("• Nenhum compromisso hoje.");
  } else {
    for (const ev of sortedEvents) {
      const timeLabel = ev.start.length <= 10 ? "Dia todo" : dates.format(ev.start, "HH:mm");
      lines.push("• " + timeLabel + " " + ev.title);
    }
  }
  lines.push("");
  lines.push("Emails importantes:");
  if (importantEmails.length === 0) {
    lines.push("• Nenhum email importante.");
  } else {
    for (const em of importantEmails) {
      lines.push("• " + em.from_name + ": " + em.subject);
    }
  }
  lines.push("");
  const daily = weather.daily || {};
  const tMax = daily.temperature_2m_max ? daily.temperature_2m_max[0] : null;
  const tMin = daily.temperature_2m_min ? daily.temperature_2m_min[0] : null;
  const rain = daily.precipitation_probability_max ? daily.precipitation_probability_max[0] : null;
  lines.push("Tempo em " + loc.name + ": " + tMin + "°C a " + tMax + "°C, " + rain + "% de chance de chuva.");

  const text = lines.join("\n");
  await notify.send({ text });
}

async function run() {
  const from = dates.today();
  const to = dates.addDays(from, params.dias);
  const emails = await gmail.search({ query: params.palavrasChave, days: 30, max: 30 });
  const bills = [];
  for (const e of emails) {
    const text = (e.subject || "") + " " + (e.snippet || "");
    const due = dates.parse(text);
    if (!due) continue;
    if (dates.isBefore(due, from)) continue;
    if (dates.isBefore(to, due)) continue;
    const amountText = money.find(text);
    if (!amountText) continue;
    bills.push({ ...e, due, amountText });
  }
  if (bills.length === 0) {
    log("Nenhuma conta vencendo na janela.");
    return;
  }
  bills.sort((a, b) => (dates.isBefore(a.due, b.due) ? -1 : dates.isBefore(b.due, a.due) ? 1 : 0));
  let total = 0;
  const lines = [];
  for (const b of bills) {
    const label = await write.billLabel(b);
    const value = money.parse(b.amountText);
    if (value) total += value;
    lines.push(`• ${dates.format(b.due, "dd/MM")} — ${label.text}: ${b.amountText}`);
  }
  const text = `Contas vencendo nos próximos ${params.dias} dias:\n\n${lines.join("\n")}\n\nTotal: ${money.format(total, "BRL")}`;
  await notify.send({ text });
}

