async function run() {
  const emails = await gmail.search({
    query: "in:inbox is:unread",
    days: params.days,
    unread: true,
    max: params.max
  });

  let archivedCount = 0;
  const archivedNames = [];

  for (const email of emails) {
    const judgment = await judge.newsletter(email);
    if (judgment.p >= 0.5) {
      await gmail.archive({ id: email.id });
      archivedCount++;
      archivedNames.push(email.from_name || email.from);
    }
  }

  let text;
  if (archivedCount === 0) {
    text = "No unread newsletters or promos to archive tonight.";
  } else {
    const noun = archivedCount === 1 ? "newsletter/promo" : "newsletters/promos";
    text = "Inbox cleanup done: archived " + archivedCount + " " + noun + " (" + archivedNames.join(", ") + ").";
  }

  await notify.send({ text });
}

async function run() {
