}

async function run() {
  const from = dates.startOfDay(dates.today(), 1);
  const to = dates.startOfDay(dates.today(), 8);
  const events = await calendar.events({ from, to });

  const sections = [];
  for (let i = 0; i < 7; i++) {
    const day = dates.addDays(from, i);
    const dayEvents = events
      .filter(e => dates.sameDay(e.start, day))
      .sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

    const header = dates.format(day, "EEE dd/MM");
    const lines = [];
    if (dayEvents.length === 0) {
      lines.push("• nothing scheduled");
    } else {
      for (const e of dayEvents) {
        const isAllDay = typeof e.start === "string" && e.start.length <= 10;
        const time = isAllDay ? "All day" : dates.format(e.start, "HH:mm");
        lines.push(`• ${time} ${e.title}`);
      }
    }
    sections.push(`${header}\n${lines.join("\n")}`);
  }

  const text = "Your week ahead:\n\n" + sections.join("\n\n");
  log(text);
  await notify.send({ text });
}

