async function run() {
  function extractTrackingCode(text) {
    const keywordMatch = text.match(/(tracking(?:\s*number)?|c[oó]digo de rastreio|rastreamento)\s*[:\-]?\s*/i);
    if (!keywordMatch) return null;
    const after = text.slice(keywordMatch.index + keywordMatch[0].length);
    const codeMatch = after.match(/^[A-Za-z0-9]{8,20}/);
    if (!codeMatch) return null;
    const code = codeMatch[0].toUpperCase();
    if (!/[0-9]/.test(code) || !/[A-Z]/.test(code)) return null;
    return code;
  }

  const emails = await gmail.search({ query: params.searchQuery, days: params.diasBusca, max: 20 });

  const found = [];
  const seen = new Set();
  for (const email of emails) {
    const text = `${email.subject || ''} ${email.snippet || ''}`;
    const code = extractTrackingCode(text);
    if (!code || seen.has(code)) continue;
    seen.add(code);
    found.push({ email, code });
  }

  if (found.length === 0) {
    log('No shipping emails with a tracking code found.');
    return;
  }

  const delivered = state.get('delivered_codes') || [];
  const newDelivered = [];
  const lines = [];

  for (const item of found) {
    const info = await http.getJSON(`https://api.trackingmore.example/v1/track?code=${item.code}`);
    if (!info || !info.status) continue;
    const status = info.status;
    if (status === 'delivered' && delivered.includes(item.code)) continue;

    const label = await write.packageLabel({ email: item.email, tracking: info });
    const statusText = status.replace(/_/g, ' ');
    let line = `• ${item.code} (${label.text}): ${statusText}`;
    if (info.last_event) line += ` — ${info.last_event}`;
    if (info.eta && status !== 'delivered' && status !== 'out_for_delivery') {
      line += `, ETA ${dates.format(info.eta, 'MMM d, yyyy')}`;
    }
    lines.push(line);
    if (status === 'delivered') newDelivered.push(item.code);
  }

  if (lines.length === 0) {
    log('No new package status to report.');
    return;
  }

  await notify.send({ text: `📦 Package status\n\n${lines.join('\n')}` });

  const updatedDelivered = Array.from(new Set([...delivered, ...newDelivered])).slice(-50);
  state.set('delivered_codes', updatedDelivered);
}

