async function run() {
  const nowIso = now();
  const tomorrowStart = dates.startOfDay(nowIso, 1);
  const dayAfterStart = dates.startOfDay(nowIso, 2);

  const events = await calendar.events({ from: tomorrowStart, to: dayAfterStart });

  const meetings = (events || []).filter(e => e.attendees && e.attendees.length > 0);
  if (meetings.length === 0) {
    log("Nenhuma reunião de amanhã com convidados.");
    return;
  }

  const dayLabel = dates.format(tomorrowStart, "dd/MM");
  const lines = [];
  lines.push(`Preparação para amanhã (${dayLabel})`);

  for (const meeting of meetings) {
    const timeLabel = dates.format(meeting.start, "HH:mm");
    lines.push("");
    lines.push(`${timeLabel} ${meeting.title}`);

    for (const attendee of meeting.attendees) {
      const emails = await gmail.search({
        query: `from:${attendee}`,
        days: params.dias,
        max: params.maxEmails
      });

      for (const em of emails) {
        const summary = await write.resumoEmail(em);
        const name = em.from_name || attendee;
        const semResposta = em.replied ? "" : " (sem resposta)";
        lines.push(`• ${name} — "${em.subject}": ${summary.text}${semResposta}`);
      }
    }
  }

  if (lines.length <= 1) {
    log("Reuniões com convidados encontradas, mas sem emails recentes.");
    return;
  }

  const text = lines.join("\n");
  await notify.send({ text });
}

async function run() {
  const url = "https://api.exchangerate.example/v1/latest?base=USD&symbols=BRL";
  const data = await http.getJSON(url);
  if (!data || !data.rates || typeof data.rates.BRL !== 'number') {
    log('Resposta invalida da API de cambio');
    return;
  }
  const rate = data.rates.BRL;
  const threshold = params.threshold;
  log('Cotacao USD->BRL: ' + rate + ' (limite ' + threshold + ')');
  if (rate > threshold) {
    const text = '💵 USD→BRL is at ' + rate.toFixed(2) + ', above your ' + threshold.toFixed(2) + ' threshold.';
    await notify.send({ text });
  }
}

async function run() {
  const items = await gmail.search({
    query: "in:inbox -from:me",
    days: params.lookback_days,
    max: 50
  });

  const nowIso = now();
  const candidates = [];

  for (const item of items) {
    if (item.replied) continue;
    const waitingDays = dates.diffDays(item.date, nowIso);
    if (waitingDays <= params.min_days) continue;
    const j = await judge.needs_reply(item);
    if (j.p >= 0.5) {
      candidates.push({ item, waitingDays });
    }
  }

  if (candidates.length === 0) return;

  candidates.sort((a, b) => (dates.isBefore(a.item.date, b.item.date) ? -1 : 1));

  const lines = candidates.map(
    (c) =>
      `• ${c.item.from_name} — "${c.item.subject}" (since ${dates.format(c.item.date, "MMM d")})`
  );

  const text = `Waiting on your reply (${params.min_days}+ days):\n\n${lines.join("\n")}`;

  await notify.send({ text });
}

async function run() {
  const today = dates.today();
  const tomorrow = dates.addDays(today, 1);
  const from = today;
  const to = dates.addDays(today, 2);

  const events = await calendar.events({ from, to });

  const calendarName = params.calendarName;
  const prefix = 'Aniversário de ';

  const todayList = [];
  const tomorrowList = [];

  for (const e of events) {
    if (e.calendar !== calendarName) continue;
    const name = e.title.startsWith(prefix) ? e.title.slice(prefix.length) : e.title;
    if (dates.sameDay(e.start, today)) {
      todayList.push(name);
    } else if (dates.sameDay(e.start, tomorrow)) {
      tomorrowList.push(name);
    }
  }

  if (todayList.length === 0 && tomorrowList.length === 0) {
    log('Nenhum aniversário hoje ou amanhã.');
    return;
  }

  const lines = ['🎂 Aniversários', ''];
  if (todayList.length > 0) {
    lines.push(`Hoje (${dates.format(today, 'dd/MM')}): ${todayList.join(', ')}`);
  }
  if (tomorrowList.length > 0) {
    lines.push(`Amanhã (${dates.format(tomorrow, 'dd/MM')}): ${tomorrowList.join(', ')}`);
  }

  await notify.send({ text: lines.join('\n') });
}
